+(function () {
+  const form = document.getElementById('contact-form');
+  const status = document.getElementById('form-status');
+
+  const fields = {
+    name: {
+      input: document.getElementById('name'),
+      error: document.getElementById('name-error'),
+      validate(v) {
+        if (!v.trim()) return 'Error: Enter your full name.';
+        if (v.trim().length < 2) return 'Error: Full name must be at least 2 characters.';
+        return '';
+      },
+    },
+    email: {
+      input: document.getElementById('email'),
+      error: document.getElementById('email-error'),
+      validate(v) {
+        if (!v.trim()) return 'Error: Enter your email address.';
+        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (!re.test(v.trim())) return 'Error: Enter a valid email like name@example.com.';
+        return '';
+      },
+    },
+    phone: {
+      input: document.getElementById('phone'),
+      error: document.getElementById('phone-error'),
+      validate(v) {
+        const trimmed = v.trim();
+        if (!trimmed) return '';
+        if (!/^[+\d\s\-().]+$/.test(trimmed)) {
+          return 'Error: Phone may only contain digits, spaces, and the characters + - ( ).';
+        }
+        const digits = trimmed.replace(/\D/g, '');
+        if (digits.length < 10 || digits.length > 15) {
+          return 'Error: Phone must contain 10 to 15 digits.';
+        }
+        return '';
+      },
+    },
+  };
+
+  function setError(field, message) {
+    if (message) {
+      field.error.textContent = message;
+      field.error.hidden = false;
+      field.input.setAttribute('aria-invalid', 'true');
+    } else {
+      field.error.textContent = '';
+      field.error.hidden = true;
+      field.input.removeAttribute('aria-invalid');
+    }
+  }
+
+  Object.values(fields).forEach((f) => {
+    f.input.addEventListener('blur', () => setError(f, f.validate(f.input.value)));
+    f.input.addEventListener('input', () => {
+      if (f.input.getAttribute('aria-invalid') === 'true') {
+        setError(f, f.validate(f.input.value));
+      }
+    });
+  });
+
+  form.addEventListener('submit', (e) => {
+    e.preventDefault();
+    status.textContent = '';
+    status.classList.remove('success');
+
+    let firstInvalid = null;
+    Object.values(fields).forEach((f) => {
+      const msg = f.validate(f.input.value);
+      setError(f, msg);
+      if (msg && !firstInvalid) firstInvalid = f.input;
+    });
+
+    if (firstInvalid) {
+      firstInvalid.focus();
+      status.textContent = 'Please fix the errors above and try again.';
+      return;
+    }
+
+    status.textContent = 'Thanks! Your message has been sent. We\u2019ll get back to you soon.';
+    status.classList.add('success');
+    form.reset();
+  });
+})();
+
