+    console.log('-', v.id, '|', v.impact, '|', v.help);
+    for (const n of v.nodes) console.log('  ', n.target.join(' '));
+  }
+  console.log('Passes:', results.passes.length);
+  console.log('Incomplete:', results.incomplete.map(i => i.id).join(', '));
+})();
+
